function sourceAssetTreeHtml(rows,selected,query=''){const byId=new Map(rows.map(a=>[String(a.ActivaID),{...a,children:[]}])),roots=[];for(const node of byId.values()){const parent=String(node.ParentActivaID||'');if(parent&&parent!==String(node.ActivaID)&&byId.has(parent))byId.get(parent).children.push(node);else roots.push(node)}const term=query.trim().toLocaleLowerCase('nl'),visible=node=>!term||String(node.Naam).toLocaleLowerCase('nl').includes(term)||node.children.some(visible),render=node=>{if(!visible(node))return'';const children=node.children.filter(visible),open=Boolean(term)||sourceExpandedAssets.has(String(node.ActivaID)),toggle=children.length?'<button type="button" data-source-toggle="'+node.ActivaID+'" aria-expanded="'+(open?'true':'false')+'" style="width:24px;height:24px;padding:0;border:0;background:transparent;cursor:pointer">'+(open?'▼':'▶')+'</button>':'<span style="display:inline-block;width:24px"></span>';return'<div><div style="display:flex;align-items:center;gap:7px;min-height:34px;padding:4px 6px">'+toggle+'<label style="display:flex;align-items:center;gap:8px"><input type="checkbox" value="'+node.ActivaID+'" '+(selected.has(String(node.ActivaID))?'checked':'')+'> <span>'+esc(node.Naam)+'</span></label></div>'+(children.length?'<div '+(open?'':'hidden')+' style="margin-left:24px;padding-left:8px;border-left:1px solid #d6e0e8">'+children.map(render).join('')+'</div>':'')+'</div>'};return roots.map(render).join('')}
function renderSourceAssetTree(){const box=document.getElementById('sourceLinkAssets');if(!box)return;box.innerHTML=sourceAssetRows.length?sourceAssetTreeHtml(sourceAssetRows,sourceSelectedAssets,document.getElementById('sourceAssetSearch').value):'<p>Geen activa beschikbaar.</p>';box.querySelectorAll('input[type=checkbox]').forEach(input=>input.onchange=()=>{if(input.checked)sourceSelectedAssets.add(input.value);else sourceSelectedAssets.delete(input.value)});box.querySelectorAll('[data-source-toggle]').forEach(button=>button.onclick=()=>{const id=button.dataset.sourceToggle;if(sourceExpandedAssets.has(id))sourceExpandedAssets.delete(id);else sourceExpandedAssets.add(id);renderSourceAssetTree()})}
async function openSourceAssetLinks(type,id,title){sourceLinkType=type;sourceLinkId=id;sourceLinkTitle=title;const modal=ensureSourceLinkModal(),box=document.getElementById('sourceLinkAssets'),status=document.getElementById('sourceLinkStatus'),folderRow=document.getElementById('sourceFolderRow');document.getElementById('sourceAssetSearch').value='';modal.style.display='flex';document.getElementById('sourceLinkTitle').textContent=(type==='document'?'Bestand beheren':'E-mail koppelen')+' · '+title;folderRow.style.display=type==='document'?'block':'none';box.innerHTML='<p>Activa laden…</p>';status.textContent='';try{const requests=[sourceLinkRequest('document_api.php?action=source_links&type='+encodeURIComponent(type)+'&id='+encodeURIComponent(id))];if(type==='document')requests.push(sourceLinkRequest('document_api.php?action=folders'),sourceLinkRequest('document_api.php?action=organize_document&id='+encodeURIComponent(id)));const data=await Promise.all(requests),links=data[0];sourceAssetRows=links.assets||[];sourceSelectedAssets=new Set((links.asset_ids||[]).map(String));sourceExpandedAssets=new Set(sourceAssetRows.filter(a=>!a.ParentActivaID).map(a=>String(a.ActivaID)));renderSourceAssetTree();if(type==='document'){sourceOriginalMap=Number(data[2].document.MapID);document.getElementById('sourceFolder').innerHTML=data[1].folders.map(f=>'<option value="'+f.MapID+'" '+(Number(f.MapID)===sourceOriginalMap?'selected':'')+'>'+esc(f.Pad)+'</option>').join('')}}catch(e){box.innerHTML='';status.textContent=e.message;status.className='error'}}
async function saveSourceLinks(){const button=document.getElementById('saveSourceLinks'),status=document.getElementById('sourceLinkStatus'),assetIds=[...sourceSelectedAssets].map(Number);button.disabled=true;button.textContent='Opslaan…';status.textContent='';try{if(sourceLinkType==='document'){const mapId=Number(document.getElementById('sourceFolder').value);if(mapId!==sourceOriginalMap)await sourceLinkRequest('document_api.php?action=organize_document&id='+encodeURIComponent(sourceLinkId),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({map_id:mapId})})}await sourceLinkRequest('document_api.php?action=source_links&type='+encodeURIComponent(sourceLinkType)+'&id='+encodeURIComponent(sourceLinkId),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({asset_ids:assetIds,title:sourceLinkTitle})});status.className='';status.textContent='✓ De wijzigingen zijn opgeslagen.';setTimeout(()=>document.getElementById('sourceLinkModal').style.display='none',700)}catch(e){status.className='error';status.textContent=e.message}finally{button.disabled=false;button.textContent='Wijzigingen opslaan'}}
function bindSourceAssetButtons(){result.querySelectorAll('.link-assets').forEach(btn=>{if(btn.dataset.bound)return;btn.dataset.bound='1';btn.onclick=()=>openSourceAssetLinks(btn.dataset.sourceType,btn.dataset.sourceId,btn.dataset.sourceTitle)})}
function enhanceSources(){const restoredBack=result.querySelector('.back-top button');if(restoredBack)restoredBack.onclick=()=>window.scrollTo({top:0,behavior:'smooth'});const sources=[...result.querySelectorAll('.source')];if(!sources.length||!result.querySelector('.source:not([id])'))return;sources.forEach((source,index)=>source.id='bron-'+(index+1));const answer=result.querySelector('.answer:not(.error)');if(answer)answer.innerHTML=answer.innerHTML.replace(/\[Bron\s+(\d+)\]/giu,(match,number)=>{const source=sources[Number(number)-1],link=source?.querySelector('a');return source&&link?'<a class="source-citation" href="'+esc(link.getAttribute('href'))+'"'+(link.hasAttribute('download')?' download':'')+' title="Bron '+number+' direct openen">'+match+'</a>':match});result.querySelector('.back-top')?.remove();const back=document.createElement('div');back.className='back-top';back.innerHTML='<button class="btn" type="button">↑ Terug naar boven</button>';back.querySelector('button').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});result.appendChild(back);sessionStorage.setItem(resultsKey,result.innerHTML)}
new MutationObserver(()=>queueMicrotask(()=>{enhanceSources();bindSourceAssetButtons()})).observe(result,{childList:true,subtree:true});queueMicrotask(()=>{enhanceSources();bindSourceAssetButtons()});
const autoSyncAccounts=<?=json_encode($autoSyncAccounts)?>;async function autoSyncMail(){for(const account of autoSyncAccounts){let offset=0;for(let batch=0;batch<100;batch++){const data=new FormData();data.set('csrf',csrf);data.set('account',String(account));data.set('action','sync_recent');data.set('offset',String(offset));try{const response=await fetch('mail_sync.php?account='+encodeURIComponent(account),{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrf},body:data});const payload=await response.json();if(!response.ok||!payload.ok)break;if(payload.csrf)csrf=payload.csrf;if(payload.done)break;offset=Number(payload.next||0)}catch(error){break}}}}if(autoSyncAccounts.length){setTimeout(autoSyncMail,3000);setInterval(autoSyncMail,1800000)}
</script></body></html>
